INSERT INTO trips (id, slug, title, summary, days, status, is_featured, rank, created_at, updated_at) VALUES (1, 'tokyo-sakura-5days', '東京櫻花五日：新宿、上野、河口湖賞櫻深度之旅', '三月底四月初櫻花季限定，走訪新宿御苑、上野公園、河口湖，近距離眺望富士山與盛開櫻花。', 5, 'published', 1, 1, '2026-08-08 14:39:25', '2026-08-08 14:39:25');
INSERT INTO trips (id, slug, title, summary, days, status, is_featured, rank, created_at, updated_at) VALUES (2, 'kyoto-autumn-6days', '京都賞楓六日：清水寺、嵐山、伏見稻荷古都巡禮', '十一月楓紅正盛，深度走訪清水寺、嵐山竹林、伏見稻荷千本鳥居，體驗古都秋日風情。', 6, 'published', 1, 2, '2026-08-08 14:39:25', '2026-08-08 14:39:25');
INSERT INTO trips (id, slug, title, summary, days, status, is_featured, rank, created_at, updated_at) VALUES (3, 'hokkaido-onsen-5days', '北海道溫泉美食五日：登別、小樽、札幌雪國饗宴', '冬季限定，登別地獄谷溫泉、小樽運河、札幌湯咖哩與海鮮市場，暖心暖胃的北國之旅。', 5, 'published', 0, 3, '2026-08-08 14:39:25', '2026-08-08 14:39:25');
INSERT INTO trips (id, slug, title, summary, days, status, is_featured, rank, created_at, updated_at) VALUES (4, 'seoul-family-4days', '首爾親子四日：樂天世界、南山塔輕鬆遊', '安排大量親子友善景點與適度自由活動時間，適合帶小朋友一起出遊的家庭行程。', 4, 'published', 0, 4, '2026-08-08 14:39:25', '2026-08-08 14:39:25');
INSERT INTO trips (id, slug, title, summary, days, status, is_featured, rank, created_at, updated_at) VALUES (5, 'taipei-101-food-3days', '台北深度小旅行三日：101、在地美食巡禮', '獻給國旅愛好者的台北深度行程，走訪信義區、大稻埕，品嚐在地小吃與精緻餐廳。', 3, 'published', 0, 5, '2026-08-08 14:39:25', '2026-08-08 14:39:25');
INSERT INTO trips (id, slug, title, summary, days, status, is_featured, rank, created_at, updated_at) VALUES (6, 'kyoto-spring-draft', '京都春季試辦行程（草稿）', '尚在規劃中的春季行程草稿，內容尚未確認，不對外公開。', 5, 'draft', 0, 0, '2026-08-08 14:39:25', '2026-08-08 14:39:25');
