INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (1, 1, 'highlights', 0, '{"html":"<p><strong>經典賞櫻路線</strong> ~ 新宿御苑、上野公園、河口湖三大賞櫻名所一次收藏</p><p>本行程專為賞櫻旺季規劃，避開人潮擁擠的熱門時段，並前往河口湖眺望富士山與湖畔櫻花並列的經典畫面。</p>"}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (2, 1, 'flight', 1, '{"legs":[{"label":"去程","date":"2027-03-25","airline":"中華航空","fromCode":"TPE","fromName":"桃園機場","toCode":"NRT","toName":"東京成田機場","departTime":"08:30","arriveTime":"12:55","duration":"3h25m"},{"label":"回程","date":"2027-03-29","airline":"中華航空","fromCode":"NRT","fromName":"東京成田機場","toCode":"TPE","toName":"桃園機場","departTime":"14:10","arriveTime":"16:50","duration":"3h40m"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (3, 1, 'daily_itinerary', 2, '{"days":[{"day":1,"title":"桃園機場 → 東京成田機場 → 入住新宿飯店","html":"<p>集合於桃園機場，搭乘豪華客機飛往東京成田機場，抵達後專車前往新宿地區辦理入住。</p>","meals":{"breakfast":"","lunch":"","dinner":"機上精緻簡餐"},"hotel":"新宿華盛頓飯店或同級"},{"day":2,"title":"新宿御苑賞櫻 → 明治神宮 → 表參道自由活動","html":"<p>上午前往新宿御苑漫步賞櫻，隨後參觀明治神宮，下午於表參道自由活動、逛街購物。</p>","meals":{"breakfast":"飯店內早餐","lunch":"日式定食料理","dinner":""},"hotel":"新宿華盛頓飯店或同級"},{"day":3,"title":"河口湖畔賞櫻 → 富士山展望 → 溫泉飯店住宿","html":"<p>專車前往河口湖，欣賞富士山與湖畔櫻花並列的經典畫面，晚間入住溫泉飯店放鬆身心。</p>","meals":{"breakfast":"飯店內早餐","lunch":"湖畔餐廳","dinner":"溫泉飯店會席料理"},"hotel":"河口湖溫泉飯店或同級"},{"day":4,"title":"上野公園賞櫻 → 淺草寺 → 台場自由活動","html":"<p>上午於上野公園賞櫻，參觀淺草寺雷門，下午於台場自由活動。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"新宿華盛頓飯店或同級"},{"day":5,"title":"成田機場 → 桃園機場","html":"<p>專車前往成田機場，搭機返回溫暖的家。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"溫暖的家"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (4, 2, 'highlights', 0, '{"html":"<p><strong>深度慢旅</strong> ~ 六天五夜完整停留京都，避開走馬看花的緊湊行程</p><p>京都是日本賞楓最具代表性的城市，讓旅客有充分時間感受古都氛圍。</p>"}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (5, 2, 'flight', 1, '{"legs":[{"label":"去程","date":"2026-11-14","airline":"星宇航空","fromCode":"TPE","fromName":"桃園機場","toCode":"KIX","toName":"大阪關西機場","departTime":"09:10","arriveTime":"12:40","duration":"3h30m"},{"label":"回程","date":"2026-11-19","airline":"星宇航空","fromCode":"KIX","fromName":"大阪關西機場","toCode":"TPE","toName":"桃園機場","departTime":"13:40","arriveTime":"16:00","duration":"3h20m"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (6, 2, 'daily_itinerary', 2, '{"days":[{"day":1,"title":"桃園機場 → 大阪關西機場 → 京都入住","html":"<p>搭機飛往大阪關西機場，專車接送前往京都入住。</p>","meals":{"breakfast":"","lunch":"","dinner":"機上精緻簡餐"},"hotel":"京都站前飯店或同級"},{"day":2,"title":"清水寺 → 二年坂三年坂 → 祇園花見小路","html":"<p>參觀世界遺產清水寺，漫步二年坂三年坂，於祇園花見小路感受古都風情。</p>","meals":{"breakfast":"飯店內早餐","lunch":"京都風味料理","dinner":""},"hotel":"京都站前飯店或同級"},{"day":3,"title":"嵐山竹林小徑 → 渡月橋 → 天龍寺","html":"<p>走訪嵐山竹林小徑、渡月橋，參觀世界遺產天龍寺庭園。</p>","meals":{"breakfast":"飯店內早餐","lunch":"嵐山湯豆腐料理","dinner":""},"hotel":"京都站前飯店或同級"},{"day":4,"title":"伏見稻荷大社千本鳥居 → 東福寺賞楓","html":"<p>參拜伏見稻荷大社千本鳥居，前往東福寺欣賞楓紅美景。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"京都站前飯店或同級"},{"day":5,"title":"奈良公園 → 東大寺 → 大阪心齋橋自由活動","html":"<p>前往奈良公園與小鹿互動，參觀東大寺，晚間於大阪心齋橋自由活動。</p>","meals":{"breakfast":"飯店內早餐","lunch":"奈良鄉土料理","dinner":""},"hotel":"大阪市區飯店或同級"},{"day":6,"title":"大阪關西機場 → 桃園機場","html":"<p>專車前往關西機場，搭機返回溫暖的家。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"溫暖的家"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (7, 3, 'highlights', 0, '{"html":"<p><strong>雪國美食巡禮</strong> ~ 連續兩晚溫泉飯店住宿，深度品嚐北海道在地美食</p><p>寒冬中最療癒的旅程，包含湯咖哩、成吉思汗烤肉與二條市場現撈海鮮。</p>"}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (8, 3, 'flight', 1, '{"legs":[{"label":"去程","date":"2027-01-10","airline":"中華航空","fromCode":"TPE","fromName":"桃園機場","toCode":"CTS","toName":"新千歲機場","departTime":"07:50","arriveTime":"12:30","duration":"4h40m"},{"label":"回程","date":"2027-01-14","airline":"中華航空","fromCode":"CTS","fromName":"新千歲機場","toCode":"TPE","toName":"桃園機場","departTime":"13:50","arriveTime":"17:20","duration":"4h30m"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (9, 3, 'daily_itinerary', 2, '{"days":[{"day":1,"title":"桃園機場 → 新千歲機場 → 登別溫泉","html":"<p>搭機飛往新千歲機場，專車前往登別溫泉區入住。</p>","meals":{"breakfast":"","lunch":"","dinner":"溫泉飯店會席料理"},"hotel":"登別溫泉飯店或同級"},{"day":2,"title":"登別地獄谷 → 熊牧場 → 洞爺湖溫泉","html":"<p>參觀登別地獄谷、熊牧場，晚間入住洞爺湖溫泉飯店。</p>","meals":{"breakfast":"飯店內早餐","lunch":"成吉思汗烤肉","dinner":""},"hotel":"洞爺湖溫泉飯店或同級"},{"day":3,"title":"小樽運河 → 音樂盒博物館 → 札幌市區","html":"<p>漫步小樽運河、參觀音樂盒博物館，晚間入住札幌市區。</p>","meals":{"breakfast":"飯店內早餐","lunch":"小樽壽司","dinner":""},"hotel":"札幌市區飯店或同級"},{"day":4,"title":"白色戀人公園 → 二條市場 → 狸小路自由活動","html":"<p>參觀白色戀人公園，於二條市場品嚐現撈海鮮，晚間於狸小路自由活動。</p>","meals":{"breakfast":"飯店內早餐","lunch":"湯咖哩","dinner":""},"hotel":"札幌市區飯店或同級"},{"day":5,"title":"新千歲機場 → 桃園機場","html":"<p>專車前往新千歲機場，搭機返回溫暖的家。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"溫暖的家"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (10, 4, 'highlights', 0, '{"html":"<p><strong>輕鬆親子遊</strong> ~ 行程步調放緩，安排樂天世界、兒童大公園等親子景點</p><p>飯店選擇皆鄰近地鐵站，方便親子移動。</p>"}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (11, 4, 'flight', 1, '{"legs":[{"label":"去程","date":"2026-10-02","airline":"長榮航空","fromCode":"TPE","fromName":"桃園機場","toCode":"ICN","toName":"仁川機場","departTime":"09:00","arriveTime":"12:15","duration":"2h15m"},{"label":"回程","date":"2026-10-05","airline":"長榮航空","fromCode":"ICN","fromName":"仁川機場","toCode":"TPE","toName":"桃園機場","departTime":"13:20","arriveTime":"15:40","duration":"2h20m"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (12, 4, 'daily_itinerary', 2, '{"days":[{"day":1,"title":"桃園機場 → 仁川機場 → 首爾入住","html":"<p>搭機飛往仁川機場，專車前往首爾市區入住。</p>","meals":{"breakfast":"","lunch":"","dinner":"機上精緻簡餐"},"hotel":"首爾市區飯店或同級"},{"day":2,"title":"樂天世界 → 石村湖公園","html":"<p>整日暢遊樂天世界主題樂園，午後於石村湖公園散步。</p>","meals":{"breakfast":"飯店內早餐","lunch":"園區內自理","dinner":""},"hotel":"首爾市區飯店或同級"},{"day":3,"title":"南山首爾塔 → 明洞自由活動","html":"<p>登上南山首爾塔欣賞市景，午後於明洞自由活動、購物。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"首爾市區飯店或同級"},{"day":4,"title":"仁川機場 → 桃園機場","html":"<p>專車前往仁川機場，搭機返回溫暖的家。</p>","meals":{"breakfast":"飯店內早餐","lunch":"","dinner":""},"hotel":"溫暖的家"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (13, 5, 'highlights', 0, '{"html":"<p><strong>國旅深度行程</strong> ~ 適合外縣市旅客或想在地深度旅遊的旅客</p><p>安排 101 觀景台、大稻埕迪化街與多家在地口碑美食。</p>"}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (14, 5, 'daily_itinerary', 1, '{"days":[{"day":1,"title":"集合 → 大稻埕迪化街 → 寧夏夜市","html":"<p>台北車站集合，漫步大稻埕迪化街，晚間於寧夏夜市享用道地小吃。</p>","meals":{"breakfast":"","lunch":"","dinner":"寧夏夜市小吃"},"hotel":"台北市區飯店或同級"},{"day":2,"title":"台北101觀景台 → 象山步道 → 信義區自由活動","html":"<p>登上台北101觀景台，健行象山步道欣賞市景，午後於信義區自由活動。</p>","meals":{"breakfast":"飯店內早餐","lunch":"信義區餐廳","dinner":""},"hotel":"台北市區飯店或同級"},{"day":3,"title":"故宮博物院 → 士林夜市 → 賦歸","html":"<p>參觀故宮博物院國寶文物，午後於士林夜市採買伴手禮後賦歸。</p>","meals":{"breakfast":"飯店內早餐","lunch":"士林夜市小吃","dinner":""},"hotel":"賦歸"}]}', '2026-08-08 14:39:25');
INSERT INTO content_blocks (id, trip_id, type, sort_order, data, created_at) VALUES (15, 6, 'richtext', 0, '{"html":"<p>行程細節尚未確認，僅供後台編輯測試草稿/發布功能。</p>"}', '2026-08-08 14:39:25');
INSERT INTO content_snippets (id, name, type, data, created_at) VALUES (1, '出國旅遊安全須知', 'richtext', '{"html":"<p><strong>出國旅遊安全須知</strong></p><p>1. 請於出發前確認護照效期至少 6 個月以上。</p><p>2. 建議自行投保旅遊平安險及不便險。</p><p>3. 隨身攜帶緊急聯絡卡與旅行社 24 小時緊急聯絡電話。</p><p>4. 貴重物品請隨身攜帶，勿置於托運行李中。</p>"}', '2026-08-08 14:39:25');
